from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(cells)
    out = [row[:] for row in grid]
    if components:
        smallest = min(map(len, components))
        largest = max(map(len, components))
        for cells in components:
            color = 7 if len(cells) == smallest else (8 if len(cells) == largest else 0)
            if color:
                for r, c in cells:
                    out[r][c] = color
    return out
